package com.codeguardian.service.ai.config; import com.codeguardian.config.AIConfigProperties; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import java.util.*;
@Component @RequiredArgsConstructor public class AIModelConfigManager{private final AIConfigProperties props;public ModelProviderConfig getConfig(String name){String provider=name==null||name.isBlank()?props.getProvider():name;if(provider==null||provider.isBlank())throw new IllegalStateException("No AI model is configured"); provider=provider.toUpperCase();var c=props.getProviderConfig(provider);return ModelProviderConfig.builder().providerName(provider).baseUrl(c==null?null:c.getBaseUrl()).apiKey(c==null?null:c.getApiKey()).defaultModel(c==null?null:c.getModel()).enabled(c!=null&&Boolean.TRUE.equals(c.getEnabled())).timeout(props.getTimeout()).build();} public List<ModelProviderConfig> getAvailableConfigs(){return props.getProviders().keySet().stream().map(this::getConfig).filter(c->Boolean.TRUE.equals(c.getEnabled())).filter(c->c.getBaseUrl()!=null&&!c.getBaseUrl().isBlank()).sorted(Comparator.comparing(ModelProviderConfig::getProviderName)).toList();}}
